// Build the prompt from the profile, the table contract and the data contract. No data rows are sent to the LLM.
const table = $('Each table').first().json;
const tableProfile = $('Profile table').first().json;
const contract = $('Get contract').first().json.contract ?? null;
// Leave out zeros and empty fields, so the prompt stays short
const compact = obj => Object.fromEntries(Object.entries(obj).filter(([, v]) =>
  v !== null && v !== 0 && v !== '0' && !(Array.isArray(v) && v.length === 0)));
const columns = $('Profile columns').all().map(i => compact(i.json));
const sampled = columns[0]?.sampled_pct < 100 ? ` (counts from a ${columns[0].sampled_pct}% sample)` : '';
columns.forEach(c => delete c.sampled_pct);

const prompt = [
  `Source: ${table.source}`,
  `Working copy: cleaning.${table.source} (${tableProfile.total_rows} rows, every value is text)`,
  `Target: clean.${table.source} with these column types: ${JSON.stringify(table.columns)}`,
  `Primary key: ${table.key.length ? table.key.join(', ') : 'none (rows can repeat)'}`,
  table.api ? 'This is an API source. raw_record holds each original JSON record; json_keys counts the keys seen in it.' : '',
  '',
  'Table profile (JSON):',
  JSON.stringify(tableProfile),
  '',
  `Column profile${sampled} (JSON):`,
  JSON.stringify(columns),
  '',
  contract ? 'Data contract written by the collection agent (JSON):' : 'No data contract is stored for this source.',
  contract ? JSON.stringify(contract) : '',
].join('\n');
return [{ json: { prompt } }];

