// Check the agent's rules, sort them into safe and risky with a fixed policy (not the LLM), and turn each rule
// into SQL from a template. Unknown rule types, unknown columns or bad settings are kept as 'invalid' and never run.
const table = $('Each table').first().json;
const agent = $input.first().json;
const S = `cleaning.${table.source}`;
const columns = Object.keys(table.columns);
const jsonKeys = Object.keys($('Profile table').first().json.json_keys ?? {});

// ---- SQL building blocks: every value from the agent goes through one of these ----
const lit = v => `'${String(v).replace(/'/g, "''")}'`;
const num = v => {
  const n = Number(v);
  if (v === null || v === undefined || v === '' || !Number.isFinite(n)) throw new Error(`"${v}" is not a number`);
  return String(n);
};
const col = c => {
  if (!columns.includes(c)) throw new Error(`unknown column "${c}"`);
  return `t.${c}`;
};
const regex = p => {
  if (typeof p !== 'string' || p.length === 0 || p.length > 120) throw new Error('pattern missing or longer than 120 characters');
  new RegExp(p);  // throws on an invalid pattern
  return lit(p);
};
const loose = v => String(v).normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[\s_-]+/g, '').toLowerCase();

const DATE_FORMATS = {  // name the agent uses → [pattern that recognises it, to_timestamp() format]
  'DD/MM/YYYY HH:MI:SS': ['^[0-9]{2}/[0-9]{2}/[0-9]{4} [0-9]{2}:[0-9]{2}:[0-9]{2}$', 'DD/MM/YYYY HH24:MI:SS'],
  'DD/MM/YYYY HH:MI': ['^[0-9]{2}/[0-9]{2}/[0-9]{4} [0-9]{2}:[0-9]{2}$', 'DD/MM/YYYY HH24:MI'],
  'DD/MM/YYYY': ['^[0-9]{2}/[0-9]{2}/[0-9]{4}$', 'DD/MM/YYYY'],
  'MM/DD/YYYY HH:MI': ['^[0-9]{2}/[0-9]{2}/[0-9]{4} [0-9]{2}:[0-9]{2}$', 'MM/DD/YYYY HH24:MI'],
  'MM/DD/YYYY': ['^[0-9]{2}/[0-9]{2}/[0-9]{4}$', 'MM/DD/YYYY'],
  'MM-DD-YYYY HH:MI': ['^[0-9]{2}-[0-9]{2}-[0-9]{4} [0-9]{2}:[0-9]{2}$', 'MM-DD-YYYY HH24:MI'],
  'MM-DD-YYYY': ['^[0-9]{2}-[0-9]{2}-[0-9]{4}$', 'MM-DD-YYYY'],
  'DD-MM-YYYY': ['^[0-9]{2}-[0-9]{2}-[0-9]{4}$', 'DD-MM-YYYY'],
  'YYYY-MM-DD': ['^[0-9]{4}-[0-9]{2}-[0-9]{2}$', 'YYYY-MM-DD'],
  'YYYY/MM/DD': ['^[0-9]{4}/[0-9]{2}/[0-9]{2}$', 'YYYY/MM/DD'],
  'ISO T/Z': ['^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\\.[0-9]+)?Z?$', 'YYYY-MM-DD"T"HH24:MI:SS'],
};
const WORDS = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten'];

function condition(c) {
  const x = col(c.column);
  switch (c.op) {
    case 'lt': return `cleaning.try_numeric(${x}) < ${num(c.value)}`;
    case 'gt': return `cleaning.try_numeric(${x}) > ${num(c.value)}`;
    case 'le': return `cleaning.try_numeric(${x}) <= ${num(c.value)}`;
    case 'ge': return `cleaning.try_numeric(${x}) >= ${num(c.value)}`;
    case 'between': return `cleaning.try_numeric(${x}) between ${num(c.value)} and ${num(c.value2)}`;
    case 'not_between': return `cleaning.try_numeric(${x}) not between ${num(c.value)} and ${num(c.value2)}`;
    case 'matches': return `${x} ~* ${regex(c.value)}`;
    case 'before_column': return `cleaning.try_timestamp(${x}) < cleaning.try_timestamp(${col(c.other_column)})`;
    case 'gt_median_x': {
      const g = col(c.group_by).slice(2);
      const v = c.column;
      return `t._row in (select s._row from ${S} s join (select m.${g}, count(*) as n, ` +
        `percentile_cont(0.5) within group (order by cleaning.try_numeric(m.${v})) as med from ${S} m group by m.${g}) m ` +
        `on m.${g} = s.${g} where m.n >= 3 and cleaning.try_numeric(s.${v}) > ${num(c.value)} * m.med)`;
    }
    default: throw new Error(`unknown condition op "${c.op}"`);
  }
}
const conditions = list => {
  if (!Array.isArray(list) || list.length === 0) throw new Error('at least one condition is needed');
  return list.map(c => `(${condition(c)})`).join(' and ');
};
const partitionedDuplicates = cols =>
  `t._row in (select d._row from (select s._row, row_number() over (partition by ${cols.map(c => `s.${c}`).join(', ')} ` +
  `order by s._row) as rn from ${S} s) d where d.rn > 1)`;

// ---- the rule catalogue: run order, risk policy, and the SQL each rule becomes ----
// risky: false = safe (applied automatically), a text = why a person must approve it, or a function deciding that.
const update = (column, cond, expr, nullOnReject = true) => ({ kind: 'update', column, cond, expr, nullOnReject });
const RULES = {
  rename_key: { order: 0, risky: 'fills a column from a field with a different name', compile: (c, p) => {
    if (!table.api) throw new Error('rename_key is only for API sources');
    if (!jsonKeys.includes(p.from_key)) throw new Error(`key "${p.from_key}" does not appear in raw_record`);
    return update(c, `coalesce(btrim(${col(c)}), '') = '' and t.raw_record ? ${lit(p.from_key)}`,
                  `t.raw_record ->> ${lit(p.from_key)}`, false);
  } },
  drop_blank_rows: { order: 1, risky: false, row: true, compile: () => ({ kind: 'delete',
    cond: columns.map(c => `coalesce(btrim(t.${c}), '') = ''`).join(' and ') }) },
  drop_header_rows: { order: 1, risky: false, row: true, compile: () => ({ kind: 'delete',
    cond: `(${columns.map(c => `(t.${c} = ${lit(c)})::int`).join(' + ')}) >= ${Math.min(2, columns.length)}` }) },
  drop_rows_matching: { order: 1, risky: 'removes rows', compile: (c, p) => ({ kind: 'delete', quarantine: true,
    cond: `${col(c)} ~* ${regex(p.pattern)}` }) },
  dedupe_exact: { order: 2, risky: false, row: true, compile: () => ({ kind: 'delete',
    cond: partitionedDuplicates(table.api ? [...columns, 'raw_record::text'] : columns) }) },
  trim: { order: 3, risky: false, compile: c => {
    const x = col(c), expr = `btrim(regexp_replace(${x}, '\\s+', ' ', 'g'))`;
    return update(c, `${x} <> ${expr}`, expr);
  } },
  null_words: { order: 3, risky: false, compile: (c, p) => {
    const words = (Array.isArray(p.words) ? p.words : []).map(w => lit(String(w).trim().toLowerCase()));
    return update(c, `btrim(${col(c)}) = ''` + (words.length ? ` or lower(btrim(${col(c)})) in (${words.join(', ')})` : ''), 'null', false);
  } },
  change_case: { order: 4, risky: false, compile: (c, p) => {
    if (!['lower', 'upper'].includes(p.to)) throw new Error('"to" must be lower or upper');
    return update(c, `${col(c)} <> ${p.to}(${col(c)})`, `${p.to}(${col(c)})`);
  } },
  remove_accents: { order: 4, risky: false, compile: c =>
    update(c, `${col(c)} <> cleaning.unaccent_pt(${col(c)})`, `cleaning.unaccent_pt(${col(c)})`) },
  map_values: { order: 5,
    risky: p => Object.entries(p.mapping ?? {}).every(([from, to]) => loose(from) === loose(to))
      ? false : 'replaces values with different text',
    compile: (c, p) => {
      const entries = Object.entries(p.mapping ?? {});
      if (entries.length === 0 || entries.length > 200) throw new Error('mapping needs 1 to 200 entries');
      const x = col(c);
      const expr = `case cleaning.norm(${x}) ${entries.map(([from, to]) => `when cleaning.norm(${lit(from)}) then ${lit(to)}`).join(' ')} else ${x} end`;
      return update(c, `cleaning.norm(${x}) in (${entries.map(([from]) => `cleaning.norm(${lit(from)})`).join(', ')}) and ${x} is distinct from ${expr}`, expr);
    } },
  scale: { order: 6, risky: 'changes the size of numbers', compile: (c, p) => {
    const x = col(c);
    return update(c, `${x} ~* ${regex(p.pattern)}`,
      `trim_scale(cleaning.try_numeric(replace(regexp_replace(${x}, '[^0-9,.-]', '', 'g'), ',', '.')) * ${num(p.factor)})::text`);
  } },
  strip_text: { order: 7,
    risky: p => typeof p.pattern === 'string' && (p.pattern.startsWith('^') || p.pattern.endsWith('$'))
      ? false : 'removes text from the middle of values',
    compile: (c, p) => {
      const x = col(c), pattern = regex(p.pattern);
      return update(c, `${x} ~* ${pattern}`, `btrim(regexp_replace(${x}, ${pattern}, '', 'gi'))`);
    } },
  replace_text: { order: 7, risky: 'replaces text inside values', compile: (c, p) => {
    const x = col(c), pattern = regex(p.pattern);
    if (typeof p.replacement !== 'string' || p.replacement.length > 40) throw new Error('replacement must be text of up to 40 characters');
    return update(c, `${x} ~* ${pattern}`, `regexp_replace(${x}, ${pattern}, ${lit(p.replacement)}, 'gi')`);
  } },
  decimal_comma: { order: 8, risky: false, compile: c => {
    const x = col(c);
    return update(c, `${x} ~ '^\\s*-?[0-9.]*,[0-9]+\\s*$'`, `replace(replace(btrim(${x}), '.', ''), ',', '.')`);
  } },
  words_to_numbers: { order: 8, risky: false, compile: c => {
    const x = col(c);
    return update(c, `lower(btrim(${x})) in (${WORDS.map(lit).join(', ')})`,
      `case lower(btrim(${x})) ${WORDS.map((w, i) => `when ${lit(w)} then '${i}'`).join(' ')} end`);
  } },
  lpad: { order: 9, risky: false, compile: (c, p) => {
    const length = Number(num(p.length ?? 5)), ch = String(p.char ?? '0');
    if (length < 1 || length > 20 || ch.length !== 1) throw new Error('length must be 1-20 and char one character');
    return update(c, `${col(c)} ~ '^[0-9]+$' and length(${col(c)}) < ${length}`, `lpad(${col(c)}, ${length}, ${lit(ch)})`);
  } },
  parse_date: { order: 10, risky: 'reads dates written in other formats; day and month could be swapped', compile: (c, p) => {
    const names = (Array.isArray(p.formats) ? p.formats : []).filter(n => n !== 'YYYY-MM-DD HH:MI:SS');
    if (names.length === 0) throw new Error('no date formats given');
    const formats = names.map(n => {
      if (!DATE_FORMATS[n]) throw new Error(`unknown date format "${n}"`);
      return [n, ...DATE_FORMATS[n]];
    });
    if (new Set(formats.map(f => f[1])).size !== formats.length) {
      throw new Error('two formats have the same shape (e.g. DD/MM/YYYY and MM/DD/YYYY); only one can be used');
    }
    const x = col(c);
    const value = n => n === 'ISO T/Z' ? `left(btrim(${x}), 19)` : `btrim(${x})`;
    const expr = `case ${formats.map(([n, re, fmt]) =>
      `when btrim(${x}) ~ ${lit(re)} then to_char(cleaning.try_to_timestamp(${value(n)}, ${lit(fmt)}), 'YYYY-MM-DD HH24:MI:SS')`).join(' ')} end`;
    return update(c, `(${formats.map(([, re]) => `btrim(${x}) ~ ${lit(re)}`).join(' or ')})`, expr);
  } },
  swap_columns: { order: 11, risky: 'moves values between two columns', compile: (c, p) => {
    if (p.other_column === c) throw new Error('other_column must be a different column');
    col(p.other_column);
    return { kind: 'swap', column: c, other: p.other_column, cond: conditions(p.conditions) };
  } },
  set_value: { order: 12, risky: 'changes what values mean', compile: (c, p) => {
    const x = col(c), numeric = `cleaning.try_numeric(${x})`;
    const cond = conditions(p.conditions);
    switch (p.action) {
      case 'abs': return update(c, `${numeric} is not null and ${cond}`, `abs(${numeric})::text`);
      case 'negate': return update(c, `${numeric} is not null and ${cond}`, `(-${numeric})::text`);
      case 'divide': {
        if (Number(num(p.divisor)) === 0) throw new Error('divisor cannot be 0');
        return update(c, `${numeric} is not null and ${cond}`, `trim_scale(round(${numeric} / ${num(p.divisor)}, 6))::text`);
      }
      case 'null': return update(c, `${x} is not null and ${cond}`, 'null', false);
      default: throw new Error('action must be abs, negate, null or divide');
    }
  } },
  dedupe_key: { order: 13, risky: 'removes rows that are not exact copies', row: true, compile: (c, p) => {
    const keys = Array.isArray(p.columns) && p.columns.length ? p.columns : [c];
    keys.forEach(col);
    return { kind: 'delete', quarantine: true,
      cond: `${keys.map(k => `coalesce(btrim(t.${k}), '') <> ''`).join(' and ')} and ${partitionedDuplicates(keys)}` };
  } },
};

// ---- statements: each one records rows affected and up to 3 examples in _results ----
const examples = (e, cond) =>
  `(select coalesce(jsonb_agg(x.e), '[]'::jsonb) from (select ${e} as e from ${S} t where ${cond} limit 3) x)`;
const counted = (id, sample, dml, cte = 'changed') => [
  `insert into _results (rule_id, examples) select ${lit(id)}, ${sample};`,
  `with ${dml}`,
  `update _results set rows_affected = (select count(*) from ${cte}) where rule_id = ${lit(id)};`,
].join('\n');

function statements(id, spec, reason) {
  if (spec.kind === 'update') {
    const c = spec.column, x = `t.${c}`;
    const apply = counted(id, examples(`jsonb_build_object('before', ${x}, 'after', ${spec.expr})`, spec.cond),
      `changed as (update ${S} t set ${c} = ${spec.expr} where ${spec.cond} returning 1)`);
    const reject = spec.nullOnReject && spec.expr !== 'null'
      ? counted(id, examples(`jsonb_build_object('before', ${x}, 'after', null)`, spec.cond),
          `changed as (update ${S} t set ${c} = null where ${spec.cond} returning 1)`)
      : null;
    return [apply, reject];
  }
  if (spec.kind === 'swap') {
    const a = spec.column, b = spec.other;
    const apply = counted(id, examples(`jsonb_build_object('before', jsonb_build_array(t.${a}, t.${b}), 'after', jsonb_build_array(t.${b}, t.${a}))`, spec.cond),
      `changed as (update ${S} t set ${a} = t.${b}, ${b} = t.${a} where ${spec.cond} returning 1)`);
    const reject = counted(id, examples(`jsonb_build_object('before', jsonb_build_array(t.${a}, t.${b}), 'after', jsonb_build_array(null, null))`, spec.cond),
      `changed as (update ${S} t set ${a} = null, ${b} = null where ${spec.cond} returning 1)`);
    return [apply, reject];
  }
  // delete: rows whose content is lost go to ops.quarantine (only in the real run, not the dry run)
  const keep = spec.quarantine
    ? `, kept as (insert into ops.quarantine (run_id, source, rule_id, reason, record) ` +
      `select r.run_id, ${lit(table.source)}, ${lit(id)}, ${lit(reason)}, to_jsonb(gone) - '_row' from gone, _run r where r.mode = 'apply')`
    : '';
  const apply = counted(id, examples(`to_jsonb(t) - '_row' - 'raw_record'`, spec.cond),
    `gone as (delete from ${S} t where ${spec.cond} returning t.*)${keep}`, 'gone');
  return [apply, null];
}

// ---- check every proposed rule ----
const proposed = Array.isArray(agent.output?.rules) ? agent.output.rules : [];
const seen = new Set();
const checked = proposed.map((rule, index) => {
  const type = String(rule.rule_type ?? '');
  const def = RULES[type];
  const column = rule.column || null;
  const params = rule.params && typeof rule.params === 'object' ? rule.params : {};
  const confidence = Number.isFinite(Number(rule.confidence)) ? Number(rule.confidence) : 0;
  const base = { index, rule_type: type, column_name: column, params, reason: String(rule.reason ?? ''), confidence };
  try {
    if (!def) throw new Error(`unknown rule type "${type}"`);
    if (!def.row && type !== 'drop_rows_matching' && !column) throw new Error('column is missing');
    const signature = JSON.stringify([type, def.row ? null : column, params]);
    if (seen.has(signature)) throw new Error('same rule proposed twice');
    seen.add(signature);
    const spec = def.compile(def.row ? column : column, params);
    let risk = typeof def.risky === 'function' ? def.risky(params) : def.risky;
    if (!risk && confidence < 0.8) risk = 'has agent confidence below 0.8';
    const columnName = type === 'dedupe_key' ? (params.columns ?? [column]).join(', ') : (def.row ? null : column);
    return { ...base, column_name: columnName, order: def.order, spec, risk: risk ? 'risky' : 'safe', risk_reason: risk || null };
  } catch (error) {
    return { ...base, order: 99, spec: null, risk: null, risk_reason: error.message };
  }
});
if (checked.length === 0) {
  const why = agent.error ? `the agent failed: ${agent.error.message ?? agent.error}` : 'the agent proposed no rules';
  checked.push({ index: 0, rule_type: 'none', column_name: null, params: {}, reason: why, confidence: 0,
                 order: 99, spec: null, risk: null, risk_reason: why });
}

checked.sort((a, b) => a.order - b.order || a.index - b.index);
const rules = checked.map((r, i) => {
  const rule_id = `${table.run_id}:${table.source}:${String(i + 1).padStart(2, '0')}`;
  const [sql, reject_sql] = r.spec ? statements(rule_id, r.spec, `${r.rule_type}: ${r.reason}`) : [null, null];
  return {
    rule_id, run_id: table.run_id, source: table.source, rule_order: i + 1, rule_type: r.rule_type,
    column_name: r.column_name, params: r.params, reason: r.reason, confidence: r.confidence,
    risk: r.risk, risk_reason: r.risk_reason,
    status: r.spec ? (r.risk === 'safe' ? 'auto' : 'pending') : 'invalid',
    sql, reject_sql,
  };
});

// Dry run: apply every valid rule to the working copy in order, to count the rows each one changes
const preview_sql = [
  `create temp table _run on commit drop as select ${lit(table.run_id)}::text as run_id, 'preview'::text as mode;`,
  `create temp table _results (rule_id text, rows_affected integer, examples jsonb) on commit drop;`,
  ...rules.filter(r => r.sql).map(r => r.sql),
  `select rule_id, rows_affected, examples from _results;`,
].join('\n');

return [{ json: { rules, preview_sql, summary: agent.output?.summary ?? '' } }];

// One ops.cleaning_rules row per rule, with the dry-run count and examples.
// If the dry run failed, no rule of this table is trusted: all are marked invalid.
const proposal = $('Check rules').first().json;
const dry = $input.all().map(i => i.json);
const failed = dry.find(r => r.error);
const byId = Object.fromEntries(dry.filter(r => r.rule_id).map(r => [r.rule_id, r]));
return proposal.rules.map(r => {
  const broken = failed && r.status !== 'invalid';
  return { json: {
    rule_id: r.rule_id, run_id: r.run_id, source: r.source, rule_order: r.rule_order,
    rule_type: r.rule_type, column_name: r.column_name, params: JSON.stringify(r.params),
    reason: r.reason, confidence: r.confidence, risk: r.risk,
    risk_reason: broken ? `dry run failed: ${failed.message ?? failed.error?.message ?? failed.error}` : r.risk_reason,
    status: broken ? 'invalid' : r.status,
    rows_affected: byId[r.rule_id]?.rows_affected ?? null,
    examples: JSON.stringify(byId[r.rule_id]?.examples ?? []),
    sql: r.sql, reject_sql: r.reject_sql,
  } };
});

const table = $('Each table').first().json;
const rules = $('Rule rows').all().map(i => i.json);
const count = status => rules.filter(r => r.status === status).length;
const invalid = count('invalid');
return [{ json: {
  run_id: table.run_id,
  agent: 'cleaning',
  action: 'propose_rules',
  source: table.source,
  target_table: `clean.${table.source}`,
  status: invalid === rules.length ? 'failed' : invalid ? 'warning' : 'success',
  rows_read: $('Profile table').first().json.total_rows,
  rows_written: null,
  duration_ms: null,
  reason: `${rules.length - invalid} rules proposed: ${count('auto')} safe (applied automatically), ` +
          `${count('pending')} risky (waiting for approval), ${invalid} invalid`,
  details: JSON.stringify({
    summary: $('Check rules').first().json.summary,
    invalid: rules.filter(r => r.status === 'invalid').map(r => ({ rule_type: r.rule_type, column: r.column_name, why: r.risk_reason })),
  }),
} }];

const t = $input.first().json;
