parameters.jsCode:
// One SQL script per table, run as one transaction: rebuild the working copy from raw, apply the rules
// (auto and approved: the rule; rejected and expired: bad values become null), cast to the target types,
// move rows with a missing or repeated key to ops.quarantine, and replace clean.<table>.
const t = $('Apply each table').first().json;
const rules = $input.all().map(i => i.json).filter(r => r.rule_id);
const lit = v => `'${String(v).replace(/'/g, "''")}'`;
if (rules.length === 0) {
  return [{ json: { sql: `select jsonb_build_object('skipped', true) as result;` } }];
}
const S = `cleaning.${t.source}`;
const C = `clean.${t.source}`;
const cast = (c, type) => ({
  text: `nullif(t.${c}, '')`,
  integer: `cleaning.try_int(t.${c})`,
  smallint: `cleaning.try_int(t.${c})::smallint`,
  numeric: `round(cleaning.try_numeric(t.${c}), 2)`,
  double: `cleaning.try_numeric(t.${c})::double precision`,
  timestamp: `cleaning.try_timestamp(t.${c})`,
})[type];
const cols = Object.entries(t.columns);
const typed = cols.filter(([, type]) => type !== 'text');
const keyMissing = t.key.length ? t.key.map(k => `y.${k} is null`).join(' or ') : 'false';
const keyRank = t.key.length
  ? `row_number() over (partition by ${t.key.map(k => cast(k, t.columns[k])).join(', ')} order by t._row)`
  : '1';
const ruleSql = rules.map(r =>
  ['auto', 'approved'].includes(r.status) ? r.sql : ['rejected', 'expired'].includes(r.status) ? r.reject_sql : null);

const sql = [
  `create temp table _run on commit drop as select ${lit(t.run_id)}::text as run_id, 'apply'::text as mode;`,
  `create temp table _results (rule_id text, rows_affected integer, examples jsonb) on commit drop;`,
  `delete from ops.quarantine where source = ${lit(t.source)};`,
  t.stage_sql,
  `create temp table _before on commit drop as select count(*)::int as n from ${S};`,
  ...ruleSql.filter(Boolean),
  `create temp table _typed on commit drop as select t._row, ` +
    `${cols.map(([c, type]) => `${cast(c, type)} as ${c}`).join(', ')}, ${keyRank} as _key_rank from ${S} t;`,
  typed.length
    ? `create temp table _cast on commit drop as select jsonb_build_object(` +
      `${typed.map(([c, type]) => `${lit(c)}, count(*) filter (where nullif(btrim(t.${c}), '') is not null and ${cast(c, type)} is null)`).join(', ')}` +
      `) as failures from ${S} t;`
    : `create temp table _cast on commit drop as select '{}'::jsonb as failures;`,
  `insert into ops.quarantine (run_id, source, rule_id, reason, record) ` +
    `select r.run_id, ${lit(t.source)}, null, case when ${keyMissing} then 'key missing after cleaning' ` +
    `else 'duplicate key after cleaning; the first row was kept' end, to_jsonb(t) - '_row' ` +
    `from _typed y join ${S} t on t._row = y._row cross join _run r where ${keyMissing} or y._key_rank > 1;`,
  `truncate ${C};`,
  `insert into ${C} (${cols.map(([c]) => c).join(', ')}) ` +
    `select ${cols.map(([c]) => `y.${c}`).join(', ')} from _typed y where not (${keyMissing}) and y._key_rank = 1;`,
  `select jsonb_build_object(` +
    `'rows_before', (select n from _before), ` +
    `'rows_after_rules', (select count(*) from ${S}), ` +
    `'rows_written', (select count(*) from ${C}), ` +
    `'quarantined', (select count(*) from ops.quarantine where source = ${lit(t.source)}), ` +
    `'cast_failures', (select failures from _cast), ` +
    `'rules', (select coalesce(jsonb_agg(r order by r.rule_id), '[]'::jsonb) from _results r)) as result;`,
].join('\n');
return [{ json: { sql } }];

// Log rows: one per rule (what it changed, and the decision behind it) and one for the table (before/after counts)
const t = $('Apply each table').first().json;
const rules = $('Get rules to apply').all().map(i => i.json).filter(r => r.rule_id);
const out = $input.first().json;
const base = { run_id: t.run_id, agent: 'cleaning', source: t.source, target_table: `clean.${t.source}`, duration_ms: null };
if (out.error || !out.result) {
  const error = out.message ?? out.error?.message ?? out.error ?? 'no result';
  return [{ json: { ...base, action: 'clean_table', status: 'failed', rows_read: null, rows_written: null,
    reason: `Cleaning ${t.source} failed, clean.${t.source} is unchanged: ${error}`, details: JSON.stringify({ error }) } }];
}
const r = out.result;
if (r.skipped) {
  return [{ json: { ...base, action: 'clean_table', status: 'warning', rows_read: null, rows_written: null,
    reason: `No usable rules for ${t.source}; clean.${t.source} is unchanged`, details: JSON.stringify({}) } }];
}
const done = Object.fromEntries((r.rules ?? []).map(x => [x.rule_id, x]));
const ruleLogs = rules.map(rule => {
  const result = done[rule.rule_id];
  const applied = ['auto', 'approved'].includes(rule.status);
  const what = `${rule.rule_type}${rule.column_name ? ` on ${rule.column_name}` : ''}`;
  const n = result?.rows_affected ?? 0;
  return { ...base, action: 'apply_rule', status: 'success', rows_read: null, rows_written: n,
    reason: applied ? `${what} (${rule.status}): ${n} rows changed`
      : result ? `${what} was ${rule.status}: ${n} bad values set to null` : `${what} was ${rule.status}: nothing changed`,
    details: JSON.stringify({ rule_id: rule.rule_id, decision: rule.status, risk: rule.risk,
                              decided_by: rule.decided_by ?? null, examples: result?.examples ?? [] }) };
});
const castFailures = Object.values(r.cast_failures ?? {}).reduce((a, b) => a + b, 0);
const tableLog = { ...base, action: 'clean_table', status: 'success', rows_read: r.rows_before, rows_written: r.rows_written,
  reason: `${r.rows_before} rows in, ${r.rows_written} rows written to clean.${t.source}: ` +
          `${r.rows_before - r.rows_after_rules} removed by rules, ${r.quarantined} kept in ops.quarantine, ` +
          `${castFailures} values could not be typed and became null`,
  details: JSON.stringify({ rows_before: r.rows_before, rows_after_rules: r.rows_after_rules, rows_written: r.rows_written,
                            quarantined: r.quarantined, cast_failures: r.cast_failures }) };
return [...ruleLogs, tableLog].map(json => ({ json }));

const run = $('Tables').first().json;
const checks = $input.all().map(i => i.json);
const tables = $('Tables').all().length;
return [{ json: {
  run_id: run.run_id, agent: 'cleaning', action: 'run_complete', source: null, target_table: null,
  status: 'success', rows_read: null, rows_written: null, duration_ms: null,
  reason: `Cleaning finished for ${tables} tables. Cross-table checks: ` +
          checks.map(c => `${c.check_name} ${c.mismatches}`).join('; '),
  details: JSON.stringify({ checks }),
} }];
